		identityFiles = append(identityFiles, s)
		return nil
	})
	fs.Func("i", "Alias for --identity", func(s string) error {
		identityFiles = append(identityFiles, s)
		return nil
	})

	// Parse arguments - this is complex because we need custom behavior
	args := os.Args[1:]

	// Check for --version first
	for i := 0; i < len(args); i++ {
		if args[i] == "--version" {
			fmt.Println(version)
			os.Exit(0)
		}
