	fs.SetOutput(io.Discard)

	encrypt := fs.Bool("encrypt", false, "")
	e := fs.Bool("e", false, "")
	decrypt := fs.Bool("decrypt", false, "")
	d := fs.Bool("d", false, "")
	output := fs.String("output", "", "")
	o := fs.String("o", "", "")
	armor := fs.Bool("armor", false, "")
	a := fs.Bool("a", false, "")
	passphrase := fs.Bool("passphrase", false, "")
	p := fs.Bool("p", false, "")

	var recipients []string
	var recipientFiles []string
	var identityFiles []string

	fs.Func("recipient", "", func(s string) error {
		recipients = append(recipients, s)
		return nil
	})
	fs.Func("r", "", func(s string) error {
		recipients = append(recipients, s)
		return nil
	})
	fs.Func("recipients-file", "", func(s string) error {
		recipientFiles = append(recipientFiles, s)
		return nil
	})
	fs.Func("R", "", func(s string) error {
		recipientFiles = append(recipientFiles, s)
		return nil
	})
	fs.Func("identity", "", func(s string) error {
		identityFiles = append(identityFiles, s)
		return nil
	})
	fs.Func("i", "", func(s string) error {
		identityFiles = append(identityFiles, s)
		return nil
	})

	err := fs.Parse(os.Args[1:])
	if err != nil {
		printUsage()
		os.Exit(1)
	}

	// Merge short and long flags
	isEncrypt := *encrypt || *e
	isDecrypt := *decrypt || *d
	outputFile := *output
	if outputFile == "" {
		outputFile = *o
	}
	isArmor := *armor || *a
	isPassphrase := *passphrase || *p

	// Get remaining args (INPUT)
	args := fs.Args()
	var inputFile string
	if len(args) > 0 {
		inputFile = args[0]
	}

	// Determine mode
	if isDecrypt && isEncrypt {
		fmt.Fprintf(os.Stderr, "age: error: --encrypt and --decrypt are mutually exclusive\n")
		os.Exit(1)
	}

	if isDecrypt {
		// Decrypt mode
		data, err := readInput(inputFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			os.Exit(1)
		}

		// Try to decrypt
		plaintext, err := decryptAge(data, identityFiles)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			os.Exit(1)
		}

		err = writeOutput(outputFile, plaintext)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			os.Exit(1)
		}
	} else {
		// Encrypt mode (default)
		if isPassphrase {
			fmt.Fprintf(os.Stderr, "age: error: passphrase encryption not yet supported\n")
			os.Exit(1)
		}

		if len(recipients) == 0 && len(recipientFiles) == 0 && len(identityFiles) == 0 {
			fmt.Fprintf(os.Stderr, "age: error: missing recipients\nage: hint: did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?\nage: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
			os.Exit(1)
		}

		// Collect all recipients
		allRecipients, err := collectRecipients(recipients, recipientFiles)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			os.Exit(1)
		}

		// Read input
		data, err := readInput(inputFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			os.Exit(1)
		}

		// Encrypt
		ciphertext, err := encryptAge(data, allRecipients)
		if err != nil {
			fmt.Fprintf(os.Stderr, "age: error: %v\n", err)
			os.Exit(1)
		}

