// Simple age encryption implementation
func encryptAgeSimple(plaintext []byte, recipientKeys [][]byte) ([]byte, error) {
	if len(recipientKeys) == 0 {
		return nil, errors.New("no recipients")
	}

	// Generate ephemeral X25519 key pair
	ephemeralPriv, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		return nil, err
	}
	ephemeralPub := ephemeralPriv.PublicKey()

	// Create file header
	buf := new(bytes.Buffer)
	buf.WriteString(ageFormat + "\n")

	// For each recipient, create a stanza
	for _, pubKeyBytes := range recipientKeys {
		pubKey, err := ecdh.X25519().NewPublicKey(pubKeyBytes)
		if err != nil {
			return nil, err
		}

		// Perform X25519 key exchange
		sharedSecret, err := ephemeralPriv.ECDH(pubKey)
		if err != nil {
			return nil, err
		}

		// Derive encryption key using HKDF-SHA256
		hkdfReader := hkdf.New(sha256.New, sharedSecret, ephemeralPub.Bytes(), []byte("age-encryption.org/v1/X25519"))
		wrappedKey := make([]byte, 32)
		_, err = io.ReadFull(hkdfReader, wrappedKey)
		if err != nil {
			return nil, err
		}

		// Encrypt file key (which is derived from plaintext)
		fileKey := sha256.Sum256(plaintext)

		cipher, err := chacha20poly1305.New(wrappedKey)
		if err != nil {
			return nil, err
		}

