// ParseAgeFile parses an age format file
func parseAgeFile(data []byte) (*AgeHeader, []byte, error) {
	reader := bytes.NewReader(data)
	scanner := bufio.NewScanner(reader)

	if !scanner.Scan() {
		return nil, nil, errors.New("empty file")
	}

	format := strings.TrimSuffix(scanner.Text(), "\n")
	if !strings.HasPrefix(format, "age-encryption.org/v1") {
		return nil, nil, fmt.Errorf("invalid format: %s", format)
	}

	header := &AgeHeader{Format: format}

	// Parse stanzas
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			break
		}

		if !strings.HasPrefix(line, "->") {
			return nil, nil, fmt.Errorf("invalid stanza line: %s", line)
		}

		parts := strings.Fields(line)
		if len(parts) < 2 {
			return nil, nil, errors.New("invalid stanza")
		}

		stanza := AgeStanza{
			Type: parts[1],
			Args: parts[2:],
		}

		// Read body lines until we hit a line that doesn't start with whitespace
		bodyLines := []string{}
		for scanner.Scan() {
			bodyLine := scanner.Text()
			if bodyLine == "" || strings.HasPrefix(bodyLine, "->") {
				// Put the line back (scanner can't do this, so we'll handle it differently)
				// For now, just accumulate
				if strings.HasPrefix(bodyLine, "->") {
					// This is a parsing issue - we need to handle this better
					break
				}
				if bodyLine == "" {
					break
				}
			}
			bodyLines = append(bodyLines, bodyLine)
		}

		if len(bodyLines) > 0 {
			// Decode last line from base64
			encodedKey := bodyLines[len(bodyLines)-1]
			decoded, err := base64.StdEncoding.DecodeString(encodedKey)
			if err != nil {
				return nil, nil, err
			}
			stanza.Body = decoded
		}

		header.Stanzas = append(header.Stanzas, stanza)
	}

	// The rest is the ciphertext
	remaining, _ := io.ReadAll(reader)

	return header, remaining, nil
}

// DecryptWithIdentity attempts to decrypt with a specific identity
func decryptWithIdentity(header *AgeHeader, ciphertext []byte, identityKey []byte) ([]byte, error) {
	// For X25519 recipients, we need to match the ephemeral public key
	// and perform the key exchange

	if len(header.Stanzas) == 0 {
		return nil, errors.New("no stanzas in header")
	}

	for _, stanza := range header.Stanzas {
		if stanza.Type != "X25519" {
			continue
		}

		if len(stanza.Args) != 1 {
			continue
		}

		ephemeralPubHex := stanza.Args[0]
		ephemeralPub, err := base64.StdEncoding.DecodeString(ephemeralPubHex)
		if err != nil {
			continue
		}

		// Perform key exchange
		privKey, err := ecdh.X25519().NewPrivateKey(identityKey)
		if err != nil {
			continue
		}

		pubKey, err := ecdh.X25519().NewPublicKey(ephemeralPub)
		if err != nil {
