		recipPubKey, err := ecdh.X25519().NewPublicKey(recipPubKeyBytes)
		if err != nil {
			return nil, err
		}

		sharedSecret, err := ephemeralPriv.ECDH(recipPubKey)
		if err != nil {
			return nil, err
		}

		// Derive wrapping key
		hkdfReader := hkdf.New(sha256.New, sharedSecret, ephemeralPub.Bytes(), []byte("age-encryption.org/v1/X25519"))
		wrappedKeyDeriver := make([]byte, 32)
